const identities = new Map();
for (const brand of COMPANY_BRANDS) {
  const assetUrl = new URL('./icons/brands/' + brand.file, import.meta.url).href;
  const company = Object.freeze({ id: brand.id, name: brand.name, src: assetUrl, brand: brand.id, role: 'company' });
  const declarant = Object.freeze({ ...company, role: 'declarant' });
  for (const alias of brand.aliases) identities.set(alias.trim().toLowerCase(), company);
  for (const alias of brand.declarantAliases) identities.set(alias.trim().toLowerCase(), declarant);
}
export function companyBrand(labelOrId) {
  if (typeof labelOrId !== 'string' || labelOrId.length > 256) return null;
  return identities.get(labelOrId.trim().toLowerCase()) ?? null;
}
